ert_mode":false,"formatType":"Text","validationScript":"","description":""},{"type":"ScriptedAction","script":"(function execute() {
 var gr = new GlideRecord("sys_user");
 gr.addQuery("user_name", vaInputs.user_id);
 gr.addQuery("phone", vaInputs.officephone);
 gr.query();
 if(gr.next()) {
 vaVars.global_linkaccount_verification_userid = gr.getValue("sys_id");
 } else {
 vaVars.global_linkaccount_verification_userid = "";
 }
})()
